// Quadtree Subdivision — Algorithms, route: jsx
// Source: algorithms:supporting/9078690
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import * as d3 from 'd3';
import { useMemo } from 'react';

// ---- inlined from quadtree ----
type Point = [number, number];
type Cell = { key: string; x0: number; y0: number; x1: number; y1: number; depth: number };

/** Everything here lives in the unit square, so the chart only has to multiply by its side. */
const target: Point = [0.58, 0.46];

/** mulberry32: a fixed seed keeps the point set identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

/** Box-Muller, so the clusters fall off smoothly instead of reading as hard blobs. */
function gaussian(): number {
  return Math.sqrt(-2 * Math.log(1 - random())) * Math.cos(2 * Math.PI * random());
}

const clamp = (value: number) => Math.min(0.995, Math.max(0.005, value));

// Clustered rather than uniform: an even point cloud subdivides evenly and hides the
// adaptive depth that is the whole reason to reach for a quadtree.
const clusters = [
  { cx: 0.24, cy: 0.28, sd: 0.07, count: 130 },
  { cx: 0.74, cy: 0.72, sd: 0.05, count: 120 },
  { cx: 0.82, cy: 0.2, sd: 0.09, count: 90 },
  { cx: 0.33, cy: 0.79, sd: 0.04, count: 60 }
];

const points: Point[] = [
  ...clusters.flatMap(({ cx, cy, sd, count }) =>
    Array.from({ length: count }, (): Point => [clamp(cx + gaussian() * sd), clamp(cy + gaussian() * sd)])
  ),
  ...Array.from({ length: 100 }, (): Point => [clamp(random()), clamp(random())])
];

// extent exactly [[0,0],[1,1]] means cover() never doubles, so the root cell IS the unit square.
const tree = d3
  .quadtree<Point>()
  .extent([
    [0, 0],
    [1, 1]
  ])
  .x((d) => d[0])
  .y((d) => d[1])
  .addAll(points);

const cellKey = (x0: number, y0: number, x1: number) => `${x0}:${y0}:${x1}`;

const cells: Cell[] = [];
tree.visit((_node, x0, y0, x1, y1) => {
  cells.push({ key: cellKey(x0, y0, x1), x0, y0, x1, y1, depth: Math.round(Math.log2(1 / (x1 - x0))) });
});

const maxDepth = d3.max(cells, (c) => c.depth) ?? 0;

type Node = d3.QuadtreeInternalNode<Point> | d3.QuadtreeLeaf<Point>;
type Quad = { node: Node; x0: number; y0: number; x1: number; y1: number };

/** Squared distance from the target to a cell, zero when the target is inside it. */
function quadDistance(quad: Quad, [tx, ty]: Point): number {
  const dx = Math.max(quad.x0 - tx, 0, tx - quad.x1);
  const dy = Math.max(quad.y0 - ty, 0, ty - quad.y1);
  return dx * dx + dy * dy;
}

const visited = new Set<string>();
const pruned = new Set<string>();
let nearestPoint: Point = points[0];
let nearestDistance2 = Infinity;

const stack: Quad[] = [{ node: tree.root() as Node, x0: 0, y0: 0, x1: 1, y1: 1 }];
while (stack.length > 0) {
  const quad = stack.pop() as Quad;
  const key = cellKey(quad.x0, quad.y0, quad.x1);

  // A cell no closer than the best point found so far cannot hold a better one, so its
  // whole subtree is skipped. This is the acceleration the structure exists for.
  if (quadDistance(quad, target) >= nearestDistance2) {
    pruned.add(key);
    continue;
  }
  visited.add(key);

  if (Array.isArray(quad.node)) {
    const xm = (quad.x0 + quad.x1) / 2;
    const ym = (quad.y0 + quad.y1) / 2;
    const children: Quad[] = [
      { node: quad.node[0] as Node, x0: quad.x0, y0: quad.y0, x1: xm, y1: ym },
      { node: quad.node[1] as Node, x0: xm, y0: quad.y0, x1: quad.x1, y1: ym },
      { node: quad.node[2] as Node, x0: quad.x0, y0: ym, x1: xm, y1: quad.y1 },
      { node: quad.node[3] as Node, x0: xm, y0: ym, x1: quad.x1, y1: quad.y1 }
    ].filter((child) => child.node !== undefined);

    // Farthest pushed first so the nearest quadrant pops first: the sooner the running best
    // tightens, the more of the remaining stack the distance test throws away.
    children.sort((a, b) => quadDistance(b, target) - quadDistance(a, target));
    stack.push(...children);
  } else {
    let leaf: d3.QuadtreeLeaf<Point> | undefined = quad.node;
    do {
      const dx = leaf.data[0] - target[0];
      const dy = leaf.data[1] - target[1];
      const distance2 = dx * dx + dy * dy;
      if (distance2 < nearestDistance2) {
        nearestDistance2 = distance2;
        nearestPoint = leaf.data;
      }
      leaf = leaf.next;
    } while (leaf !== undefined);
  }
}

const visitedKeys = visited;
const prunedKeys = pruned;
const nearest = nearestPoint;
const nearestDistance = Math.sqrt(nearestDistance2);
const visitedCount = visited.size;

const MAX_SIDE = 620;
const HEADER = 30;
const CROSS = 7;

export default function Quadtree({ width }: { width: number }) {
  // Floored because the width === 0 bail runs after every hook, and a zero side would put
  // NaN into each rect below.
  const side = Math.max(1, Math.min(width, MAX_SIDE));

  const depthColor = useMemo(
    () => d3.scaleSequential([0, Math.max(1, maxDepth)], d3.interpolateCool),
    []
  );

  const rects = useMemo(
    () =>
      cells.map((cell) => ({
        key: cell.key,
        depth: cell.depth,
        pruned: prunedKeys.has(cell.key),
        visited: visitedKeys.has(cell.key),
        x: cell.x0 * side,
        y: cell.y0 * side,
        width: (cell.x1 - cell.x0) * side,
        height: (cell.y1 - cell.y0) * side
      })),
    [side]
  );

  if (width === 0) return null;

  const [tx, ty] = [target[0] * side, target[1] * side];
  const legend = d3.range(maxDepth + 1);

  return (
    <svg
      viewBox={`0 0 ${side} ${side + HEADER}`}
      width="100%"
      height={side + HEADER}
      role="img"
      aria-label={`Quadtree of ${points.length} clustered points, showing the cells searched and the subtrees pruned while finding the point nearest a target`}
      style={{ display: 'block', font: '10px sans-serif' }}
    >
      <g transform="translate(0,10)">
        <text fill="var(--muted)" y={9}>
          Cell depth
        </text>
        {legend.map((depth) => (
          <rect key={depth} x={62 + depth * 9} y={1} width={8} height={9} fill={depthColor(depth)} />
        ))}
        <rect x={72 + maxDepth * 9} y={1} width={9} height={9} fill="var(--muted)" fillOpacity={0.18} />
        <text x={85 + maxDepth * 9} y={9} fill="var(--muted)">
          pruned subtree
        </text>
        <circle cx={166 + maxDepth * 9} cy={5.5} r={3.5} fill="var(--accent)" />
        <text x={174 + maxDepth * 9} y={9} fill="var(--muted)">
          nearest of {points.length}, found by testing {visitedCount} cells
        </text>
      </g>

      <g transform={`translate(0,${HEADER})`}>
        {/* One wash per pruned node covers its entire skipped subtree, so no extra pass is needed. */}
        <g fill="var(--muted)" fillOpacity={0.18}>
          {rects
            .filter((rect) => rect.pruned)
            .map((rect) => (
              <rect key={rect.key} x={rect.x} y={rect.y} width={rect.width} height={rect.height} />
            ))}
        </g>

        <g fill="none" shapeRendering="crispEdges">
          {rects.map((rect) => (
            <rect
              key={rect.key}
              x={rect.x}
              y={rect.y}
              width={rect.width}
              height={rect.height}
              stroke={depthColor(rect.depth)}
              strokeOpacity={rect.visited ? 0.9 : 0.3}
              strokeWidth={rect.depth < 2 ? 1.2 : 0.6}
            />
          ))}
        </g>

        <g fill="var(--text)" fillOpacity={0.55}>
          {points.map((point, index) => (
            <circle key={index} cx={point[0] * side} cy={point[1] * side} r={1.5} />
          ))}
        </g>

        {/* Radius of the winning distance: every cell it misses was safe to throw away. */}
        <circle
          cx={tx}
          cy={ty}
          r={nearestDistance * side}
          fill="none"
          stroke="var(--accent)"
          strokeOpacity={0.7}
          strokeDasharray="3 3"
        />
        <g stroke="var(--accent)" strokeWidth={1.5}>
          <line x1={tx - CROSS} x2={tx + CROSS} y1={ty} y2={ty} />
          <line x1={tx} x2={tx} y1={ty - CROSS} y2={ty + CROSS} />
        </g>
        <circle cx={nearest[0] * side} cy={nearest[1] * side} r={4} fill="var(--accent)" />
      </g>
    </svg>
  );
}
